import { readFile } from "node:fs/promises"
import { join } from "node:path"

// Serves the llms.txt generated by the @asyst/atlas build — the exact file
// published with the package, so the site and the package never disagree.
export const dynamic = "force-static"

export async function GET() {
    const file = join(process.cwd(), "node_modules", "@asyst", "atlas", "dist", "llms.txt")
    const text = await readFile(file, "utf8")
    return new Response(text, {
        headers: { "Content-Type": "text/plain; charset=utf-8" },
    })
}
